# lamps: combinational logic, generated by Silinx from the truth table lamps.bool.json (edit the drawing, not this file).
# MicroPython for the ESP32 DevKit. One tick every TICK_MS milliseconds: the inputs read once at its start, the outputs
# written to their pins at its end (Silinx's synchronous reactive model: docs/SYSTEMS.md).
# Inputs: phase2 GPIO4, phase1 GPIO13, phase0 GPIO14, blink GPIO16.
# Outputs: car_r GPIO17, car_y GPIO18, car_g GPIO19, walk_r GPIO21, walk_g GPIO22.

from machine import Pin
import time

# ---- the pins
PIN_PHASE2 = Pin(4, Pin.IN)
PIN_PHASE1 = Pin(13, Pin.IN)
PIN_PHASE0 = Pin(14, Pin.IN)
PIN_BLINK = Pin(16, Pin.IN)
PIN_CAR_R = Pin(17, Pin.OUT)
PIN_CAR_Y = Pin(18, Pin.OUT)
PIN_CAR_G = Pin(19, Pin.OUT)
PIN_WALK_R = Pin(21, Pin.OUT)
PIN_WALK_G = Pin(22, Pin.OUT)

TICK_MS = 10  # the tick's period

# ---- the inputs, read once per tick
phase2 = 0
phase1 = 0
phase0 = 0
blink = 0

# ---- the outputs
car_r = 0
car_y = 0
car_g = 0
walk_r = 0
walk_g = 0


def read_inputs():
    global phase2, phase1, phase0, blink
    phase2 = PIN_PHASE2.value()
    phase1 = PIN_PHASE1.value()
    phase0 = PIN_PHASE0.value()
    blink = PIN_BLINK.value()


def write_outputs():
    PIN_CAR_R.value(car_r)
    PIN_CAR_Y.value(car_y)
    PIN_CAR_G.value(car_g)
    PIN_WALK_R.value(walk_r)
    PIN_WALK_G.value(walk_g)


# the reset state
def reset_machine():
    pass


# one tick: the outputs of the inputs
def step_machine():
    global car_r, car_y, car_g, walk_r, walk_g
    read_inputs()
    car_r = (not phase2 and phase1) or (phase2 and not phase1)
    car_y = (not phase2 and not phase1 and phase0) or (phase2 and phase1 and blink)
    car_g = not phase2 and not phase1 and not phase0
    walk_r = (not phase2 and not phase0) or (not phase1 and phase0)
    walk_g = (phase1 and phase0) or (phase2 and not phase1 and not phase0 and blink)
    write_outputs()


# the reset state, then a tick every TICK_MS milliseconds
def main():
    reset_machine()
    last = time.ticks_ms()
    while True:
        if time.ticks_diff(time.ticks_ms(), last) >= TICK_MS:
            last = time.ticks_add(last, TICK_MS)
            step_machine()


main()
